/* @author MILO-GAO(高振銘)@2020 */ package page2020.core;import java.util.List;import org.slf4j.Logger;import org.slf4j.LoggerFactory;import page2020.View;import page2020.util.EmptyUtil;import page2020.view.C3;import page2020.view.Content;import page2020.view.Element;public class Flow extends Name<Flow> {	private static Logger log = LoggerFactory.getLogger(Flow.class);	protected int code = 0;	protected View view;	protected Page page;	protected String logName;	protected int ui = 0;	protected int close = 0;	public Flow view(String path, int code, View view) {		super.name(path);		if (code >= 1000) {			this.close = (int)(code / 1000);			code = (int)(code % 1000);		}		if (code >= 10) {			this.ui = (int)(code / 10);			this.code = (int)(code % 10);		} else {			this.code = code;		}		this.view = view;		return this;	}	public Flow construct(String appName) {		App app = new App(appName, super.getName());		this.logName = app.getName() + " : ";			this.page = App.page(app.getSysCode());		if (this.ui > 0) {			this.page.setUi(this.ui);		}		if (this.close > 0) {			this.page.data("close", this.close);		}		this.page.begin(app);		if (Log.flow) {			log.info(this.logName + "Flow('" + super.getName() + "', " + this.code + ")" 				+ " elements=" + this.view.count());		}		return this;	}	public Flow automate() {		this.page.selector("html, body", C3.height("100%"));		this.page.getScripts().add(Path.page2020 + "log.js");		this.page.getScripts().add(Path.page2020 + "app.js");		this.page.getScripts().add(Path.page2020 + "page.js");		return this;	}	public Page destruct() {		this.page.end(this.view);		this.page.build();		return this.page;	}	public Flow element(Element<?, ?> source, View view) {		@SuppressWarnings("unchecked")		List<Content<?>> children = (List<Content<?>>) source.getContents();		int size = children.size();		for (int i=0; i < size; i++) {			boolean complete = false;			String childName = children.get(i).getName();			if (EmptyUtil.not(childName)) {				int index = 0;				while (index < view.count()) {					if (childName.equals(view.get(index).getName())) {						children.remove(i);						if (i >= children.size()) {							children.add(view.remove(index));						} else {							children.add(i, view.remove(index));						}						complete = true;						if (Log.element) {							log.info("Flow: element='" + childName + "'");						}						break;					} else {						index += 1;					}				}			}			if ((! complete) && children.get(i) instanceof Element<?, ?>) {				Element<?, ?> child = (Element<?, ?>) children.get(i);				if (child.count() > 0) {					this.element(child, view);				}			}		}		return this;	}	public Flow view(View view) {		return this.view(SysKey.def, 0, view);	}	public Flow view(String path, View view) {		return this.view(path, 0, view);	}	public Flow view(int code, View view) {		return this.view(SysKey.def, code, view);	}	public Flow view(Class<?> clazz) {		return this.view(SysKey.def, 0, new View().append(new Form(clazz)));	}	public Flow view(String path, Class<?> clazz) {		return this.view(path, 0, new View().append(new Form(clazz)));	}	public Flow view(int code, Class<?> clazz) {		return this.view(SysKey.def, code, new View().append(new Form(clazz)));	}	public Flow view(String path, int code, Class<?> clazz) {		return this.view(path, code, new View().append(new Form(clazz)));	}	public Flow view(Form form) {		return this.view(SysKey.def, 0, new View().append(form));	}	public Flow view(String path, Form form) {		return this.view(path, 0, new View().append(form));	}	public Flow view(int code, Form form) {		return this.view(SysKey.def, code, new View().append(form));	}	public Flow view(String path, int code, Form form) {		return this.view(path, code, new View().append(form));	}	public Flow view(Table table) {		return this.view(SysKey.def, 0, new View().append(table));	}	public Flow view(String path, Table table) {		return this.view(path, 0, new View().append(table));	}	public Flow view(int code, Table table) {		return this.view(SysKey.def, code, new View().append(table));	}	public Flow view(String path, int code, Table table) {		return this.view(path, code, new View().append(table));	}}